import random

def get_player_choice():
    """Get a valid player choice (rock, paper, scissors)."""
    while True:
        choice = input("Enter your choice (rock, paper, scissors): ").lower()
        if choice in ["rock", "paper", "scissors"]:
            return choice
        else:
            print("Invalid choice. Please enter 'rock', 'paper', or 'scissors'.")

def get_computer_choice():
    """Get a random computer choice (rock, paper, scissors)."""
    return random.choice(["rock", "paper", "scissors"])

def play_round(player_choice, computer_choice):
    """Determine the winner of a round based on the given choices."""
    if player_choice == computer_choice:
        return "It's a tie!"
    elif (player_choice == "rock" and computer_choice == "scissors") or \
         (player_choice == "paper" and computer_choice == "rock") or \
         (player_choice == "scissors" and computer_choice == "paper"):
        return f"{player_choice} beats {computer_choice}! Player {player_choice.capitalize()} wins!"
    else:
        return f"{computer_choice} covers {player_choice}! Computer wins!"

def play_game():
    """Play a single game of Rock, Paper, Scissors."""
    player_score = 0
    computer_score = 0

    while True:
        player_choice = get_player_choice()
        computer_choice = get_computer_choice()

        result = play_round(player_choice, computer_choice)
        print(result)

        if result == "Player 2 wins":
            player_score += 1
        elif result == "Computer wins":
            computer_score += 1
        else:  # Tie
            pass

        play_again = input("Do you want to play again? (yes/no): ").lower()
        if play_again != "yes":
            break

    print(f"Game over! Player score: {player_score}, Computer score: {computer_score}")

if __name__ == "__main__":
    play_game()
